import re

def parse_query_string(text):
    parsed_dict = {}

    # Splitting the URL query string on '&' characters
    queries = text.split('&')

    # Iterating through each query in the split results
    for q in queries:
        # Using regular expressions to extract key-value pairs
        match = re.match(r'^([^=]+)=([^=]+)', q)

        # If there's a match, add the key-value pair to the dictionary
        if match:
            parsed_dict[match.group(1)] = match.group(2)

    return parsed_dict

