def parse_query_string(text):
    data = {}
    pattern = r'([=\w]+)=([^&]*)'
    matches = re.findall(pattern, text)
    for match in matches:
        key = match[0].strip()
        value = match[1].strip()
        if value == '':
            data[key] = ''
        else:
            data[key] = value
