def merge_intervals(intervals):
    merged_intervals = []

    # Iterate over all pairs of consecutive intervals
    for i in range(len(intervals)):
        for j in range(i+1, len(intervals)):
            # Check if they overlap
            if intervals[i][1] <= intervals[j][0]:
                # No overlap, add the smaller interval first
                merged_intervals.append((intervals[i]))
                # Merge overlapping intervals
                while intervals[i][1] <= intervals[j][1]:
                    intervals[i].append(intervals[j])
                    del intervals[j]
                    break
                # If there's any remaining overlap, append it
                if not intervals:
                    merged_intervals.append(intervals[i])

    # Sort the merged intervals based on their start
    merged_intervals.sort(key=lambda x: x[0])

    return merged_intervals

